-- MFB-1192 recovery: definitions of the two matviews that were created by hand and
-- never lived in this repo. Captured from prod (GRAY replica) on 2026-10-28.
-- Neither was refreshed by any scheduled job, so recreating them is a one-off.
-- (data_programs and data_referrer_codes: use the files from git history.)

CREATE MATERIALIZED VIEW public.data_dates AS
SELECT date_series.date_series AS date_serial,
    to_char(date_series.date_series, 'MM/DD/YYYY'::text) AS date,
    EXTRACT(year FROM date_series.date_series) AS year,
    to_char(date_series.date_series, 'Month'::text) AS month_name,
    EXTRACT(month FROM date_series.date_series) AS month_number,
    to_char(date_series.date_series, 'Mon'::text) AS month_for_charts,
    to_char(date_series.date_series, 'MM/DD'::text) AS month_day,
    to_char(date_series.date_series, 'MM/YY'::text) AS month_year,
    EXTRACT(week FROM date_series.date_series) AS week_number,
    to_char(date_series.date_series, 'Day'::text) AS day_of_week_name,
    EXTRACT(dow FROM date_series.date_series) + 1::numeric AS day_of_week_number,
    to_char(date_series.date_series, 'Dy'::text) AS day_of_week_for_charts,
    EXTRACT(day FROM date_series.date_series) AS day_of_month_number,
    EXTRACT(doy FROM date_series.date_series) AS day_of_year_number,
    date_part('day'::text, date_series.date_series - '1899-12-30'::date::timestamp with time zone) AS excel_serial
   FROM generate_series('2000-01-01'::date::timestamp with time zone, '2040-12-31'::date::timestamp with time zone, '1 day'::interval) date_series(date_series);

